const meta = $('Захватить документ в обработку').item.json;
const document = meta.attachments;

if (!$binary?.data) {
  throw new Error(
    `Файл не скачан: ${document?.file_name ?? 'unknown'}`
  );
}

if (!document) {
  throw new Error('Метаданные документа отсутствуют');
}

// Оригинальное имя TenderPlan считаем основным.
if (document.file_name) {
  $binary.data.fileName = document.file_name;
}

return {
  json: {
    analysis_run_id: meta.analysis_run_id ?? null,
    tender_meta: meta.tender_meta,

    document: {
      document_id: document.document_id ?? null,
      document_index: document.document_index ?? null,
      file_name: document.file_name ?? null,
      file_extension: document.file_extension ?? null,
      display_name: document.display_name ?? null,
      download_url: document.download_url ?? null,
      publication_at: document.publication_at ?? null,
      source_size: document.source_size ?? null,

      // Фактические данные скачанного файла
      mime_type: $binary.data.mimeType ?? null,
      file_size: $binary.data.fileSize ?? null,
    },
  },

  binary: $binary,
};

const result = $json;

const docResult = result.documents?.[0];

if (!docResult) {
  throw new Error('Docling не вернул documents[0]');
}

if (docResult.status !== 'success') {
  throw new Error(
    `Документ Docling обработан со статусом: ${docResult.status}`
  );
}

const artifacts = Array.isArray(docResult.artifacts)
  ? docResult.artifacts
  : [];

const jsonArtifact = artifacts.find(
  artifact => artifact.artifact_type === 'json'
);

const markdownArtifact = artifacts.find(
  artifact => artifact.artifact_type === 'markdown'
);

if (!jsonArtifact?.uri) {
  throw new Error('Docling не вернул JSON artifact');
}

// Возвращаем наши исходные метаданные документа.
// Пока у нас тест с одним документом через Limit,
// поэтому привязка однозначная.
const source = $('Связать метаданные и файл').item.json;

// task_id берём из ноды отправки.
const task = $('Загрузка файла в Docling').item.json;

return {
  json: {

    analysis_run_id: source.analysis_run_id ?? null,
    // Наши данные, которые Docling вообще не знает
    tender_meta: source.tender_meta ?? null,
    document: source.document ?? null,

    // Служебная информация обработки Docling
    docling: {
      task_id: task.task_id ?? null,

      source_index: docResult.source_index ?? null,
      source_uri: docResult.source_uri ?? null,
      filename: docResult.filename ?? null,

      status: docResult.status ?? null,
      processing_time: result.processing_time ?? null,

      errors: docResult.errors ?? [],
      confidence: docResult.confidence ?? null,

      // Временные ссылки на результаты
      json_artifact: jsonArtifact,
      markdown_artifact: markdownArtifact ?? null
    }
  }
};

const doc = $json;

if (!doc || doc.schema_name !== 'DoclingDocument') {
  throw new Error('Ожидался DoclingDocument');
}


// ============================================================
// 1. ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ============================================================

function cleanText(value) {
  if (value === null || value === undefined) {
    return '';
  }

  return String(value)
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
}


function getFirstProv(node) {
  if (!Array.isArray(node?.prov) || node.prov.length === 0) {
    return {
      page_no: null,
      bbox: null,
    };
  }

  const prov = node.prov[0];

  return {
    page_no: prov.page_no ?? null,
    bbox: prov.bbox ?? null,
  };
}


// Docling использует ссылки вида:
//
// #/texts/10
// #/tables/2
// #/groups/0
function parseRef(ref) {
  if (typeof ref !== 'string') {
    return null;
  }

  const match = ref.match(/^#\/([^/]+)\/(\d+)$/);

  if (!match) {
    return null;
  }

  return {
    collection: match[1],
    index: Number(match[2]),
  };
}


// ============================================================
// 2. КОЛЛЕКЦИИ DOCLING
// ============================================================

const collections = {
  texts: Array.isArray(doc.texts)
    ? doc.texts
    : [],

  tables: Array.isArray(doc.tables)
    ? doc.tables
    : [],

  pictures: Array.isArray(doc.pictures)
    ? doc.pictures
    : [],

  groups: Array.isArray(doc.groups)
    ? doc.groups
    : [],

  key_value_items: Array.isArray(doc.key_value_items)
    ? doc.key_value_items
    : [],

  form_items: Array.isArray(doc.form_items)
    ? doc.form_items
    : [],
};


function resolveRef(ref) {
  const parsed = parseRef(ref);

  if (!parsed) {
    return null;
  }

  const collection = collections[parsed.collection];

  if (!Array.isArray(collection)) {
    return null;
  }

  const node = collection[parsed.index];

  if (!node) {
    return null;
  }

  return {
    collection: parsed.collection,
    index: parsed.index,
    node,
  };
}


// ============================================================
// 3. НОРМАЛИЗАЦИЯ ТАБЛИЦ
// ============================================================

function normalizeTable(table) {
  const data = table?.data ?? {};

  // ВАЖНО:
  // Берём table_cells, а НЕ grid.
  //
  // grid размножает объединённые ячейки.
  // Например одна merged cell на 30 колонок может
  // повториться там 30 раз.
  const sourceCells = Array.isArray(data.table_cells)
    ? data.table_cells
    : [];

  const cells = sourceCells.map((cell, index) => ({
    cell_index: index,

    row_start:
      cell.start_row_offset_idx ??
      null,

    row_end:
      cell.end_row_offset_idx ??
      null,

    col_start:
      cell.start_col_offset_idx ??
      null,

    col_end:
      cell.end_col_offset_idx ??
      null,

    row_span:
      cell.row_span ??
      1,

    col_span:
      cell.col_span ??
      1,

    text:
      cleanText(cell.text),

    column_header:
      cell.column_header ??
      false,

    row_header:
      cell.row_header ??
      false,

    row_section:
      cell.row_section ??
      false,

    fillable:
      cell.fillable ??
      false,
  }));


  // Группируем logical cells по строкам.
  const rowsMap = new Map();

  for (const cell of cells) {
    const row = cell.row_start;

    if (row === null) {
      continue;
    }

    if (!rowsMap.has(row)) {
      rowsMap.set(row, []);
    }

    rowsMap.get(row).push(cell);
  }


  const rows = [...rowsMap.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([rowIndex, rowCells]) => ({
      row_index: rowIndex,

      cells: rowCells.sort((a, b) => {
        return (a.col_start ?? 0) - (b.col_start ?? 0);
      }),
    }));


  return {
    num_rows:
      data.num_rows ??
      null,

    num_cols:
      data.num_cols ??
      null,

    orientation:
      data.orientation ??
      null,

    cells,
    rows,
  };
}


// ============================================================
// 4. МАССИВ НОРМАЛИЗОВАННЫХ BLOCKS
// ============================================================

const blocks = [];

let blockOrder = 0;


function addBlock({
  type,
  node,
  groupPath,
  sheetName,
  contentLayer,
  extra = {},
}) {
  const prov = getFirstProv(node);

  blocks.push({
    block_id:
      node.self_ref ??
      `block_${String(blockOrder + 1).padStart(5, '0')}`,

    order:
      ++blockOrder,

    type,

    label:
      node.label ??
      type,

    content_layer:
      contentLayer ??
      node.content_layer ??
      null,

    group_path:
      Array.isArray(groupPath)
        ? groupPath
        : [],

    // Для Excel особенно важно.
    sheet_name:
      sheetName ??
      null,

    source: {
      page_no:
        prov.page_no,

      bbox:
        prov.bbox,
    },

    ...extra,
  });
}


// ============================================================
// 5. КОНТРОЛЬ ОБХОДА
// ============================================================

// Защита одновременно от:
// 1. дублей;
// 2. циклических ссылок.
const visitedRefs = new Set();


// Если Docling вернёт ссылку неизвестного нам типа,
// мы больше не будем молча её игнорировать.
const unknownRefs = [];


// ============================================================
// 6. РЕКУРСИВНЫЙ ОБХОД DOCLING DOCUMENT
// ============================================================

function walkChildren(
  children,
  context = {
    groupPath: [],
    sheetName: null,
    contentLayer: 'body',
  }
) {
  if (!Array.isArray(children)) {
    return;
  }


  for (const child of children) {
    const ref = child?.$ref;

    if (!ref) {
      continue;
    }


    // Этот элемент уже обрабатывали.
    if (visitedRefs.has(ref)) {
      continue;
    }


    const resolved = resolveRef(ref);

    if (!resolved) {
      unknownRefs.push(ref);
      continue;
    }


    visitedRefs.add(ref);


    const {
      collection,
      node,
    } = resolved;


    // ========================================================
    // GROUP
    // ========================================================

    if (collection === 'groups') {
      const groupName =
        node.name ??
        node.label ??
        null;


      const newGroupPath =
        groupName
          ? [...context.groupPath, groupName]
          : [...context.groupPath];


      // Для XLSX Docling создаёт:
      //
      // group.label = sheet
      // group.name = Лист1
      const newSheetName =
        node.label === 'sheet'
          ? (
              node.name ??
              context.sheetName
            )
          : context.sheetName;


      // Сам group в blocks пока не добавляем.
      // Нам важнее его содержимое.
      walkChildren(
        node.children,
        {
          groupPath: newGroupPath,
          sheetName: newSheetName,
          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );

      continue;
    }


    // ========================================================
    // TEXT
    // ========================================================

    if (collection === 'texts') {
      const text = cleanText(node.text);

      addBlock({
        type: 'text',

        node,

        groupPath:
          context.groupPath,

        sheetName:
          context.sheetName,

        contentLayer:
          node.content_layer ??
          context.contentLayer,

        extra: {
          text,

          is_empty:
            text.length === 0,

          text_label:
            node.label ??
            'text',

          // Например section_header.
          level:
            node.level ??
            null,

          // В DOCX полезно понимать:
          // bold / italic / underline и т.д.
          formatting:
            node.formatting ??
            null,

          // Например mailto / URL.
          hyperlink:
            node.hyperlink ??
            null,
        },
      });


      // КРИТИЧЕСКИ ВАЖНО:
      //
      // В Docling text сам может быть родителем.
      //
      // Именно здесь была ошибка предыдущей версии.
      //
      // Например texts/6 в нашем DOCX содержит:
      // texts/7...
      // groups/1
      // groups/2
      // tables/0
      // ...
      walkChildren(
        node.children,
        {
          groupPath:
            context.groupPath,

          sheetName:
            context.sheetName,

          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );

      continue;
    }


    // ========================================================
    // TABLE
    // ========================================================

    if (collection === 'tables') {
      addBlock({
        type: 'table',

        node,

        groupPath:
          context.groupPath,

        sheetName:
          context.sheetName,

        contentLayer:
          node.content_layer ??
          context.contentLayer,

        extra: {
          table:
            normalizeTable(node),

          captions:
            node.captions ??
            [],

          references:
            node.references ??
            [],

          footnotes:
            node.footnotes ??
            [],
        },
      });


      // Сейчас таблицы обычно не имеют children,
      // но оставляем поддержку на будущее.
      walkChildren(
        node.children,
        {
          groupPath:
            context.groupPath,

          sheetName:
            context.sheetName,

          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );

      continue;
    }


    // ========================================================
    // PICTURE
    // ========================================================

    if (collection === 'pictures') {
      const image =
        node.image ??
        null;


      addBlock({
        type: 'picture',

        node,

        groupPath:
          context.groupPath,

        sheetName:
          context.sheetName,

        contentLayer:
          node.content_layer ??
          context.contentLayer,

        extra: {
          picture: {
            mimetype:
              image?.mimetype ??
              null,

            dpi:
              image?.dpi ??
              null,

            width:
              image?.size?.width ??
              null,

            height:
              image?.size?.height ??
              null,

            // Base64 сюда специально не переносим.
            has_embedded_image:
              Boolean(image?.uri),

            captions:
              node.captions ??
              [],
          },
        },
      });


      walkChildren(
        node.children,
        {
          groupPath:
            context.groupPath,

          sheetName:
            context.sheetName,

          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );

      continue;
    }


    // ========================================================
    // KEY VALUE
    // ========================================================

    if (collection === 'key_value_items') {
      addBlock({
        type: 'key_value',

        node,

        groupPath:
          context.groupPath,

        sheetName:
          context.sheetName,

        contentLayer:
          node.content_layer ??
          context.contentLayer,

        extra: {
          data: node,
        },
      });


      walkChildren(
        node.children,
        {
          groupPath:
            context.groupPath,

          sheetName:
            context.sheetName,

          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );

      continue;
    }


    // ========================================================
    // FORM ITEM
    // ========================================================

    if (collection === 'form_items') {
      addBlock({
        type: 'form_item',

        node,

        groupPath:
          context.groupPath,

        sheetName:
          context.sheetName,

        contentLayer:
          node.content_layer ??
          context.contentLayer,

        extra: {
          data: node,
        },
      });


      walkChildren(
        node.children,
        {
          groupPath:
            context.groupPath,

          sheetName:
            context.sheetName,

          contentLayer:
            node.content_layer ??
            context.contentLayer,
        }
      );
    }
  }
}


// ============================================================
// 7. ОБХОД BODY
// ============================================================

walkChildren(
  doc.body?.children,
  {
    groupPath: [],
    sheetName: null,
    contentLayer: 'body',
  }
);


// ============================================================
// 8. ОБХОД FURNITURE
// ============================================================
//
// В PDF здесь потенциально могут находиться:
//
// header
// footer
// page number
// и т.д.
//
// Мы их не теряем, но маркируем content_layer = furniture,
// чтобы позже можно было фильтровать.

walkChildren(
  doc.furniture?.children,
  {
    groupPath: [],
    sheetName: null,
    contentLayer: 'furniture',
  }
);


// ============================================================
// 9. СТАТИСТИКА НОРМАЛИЗОВАННОГО ДОКУМЕНТА
// ============================================================

const textBlocks =
  blocks.filter(
    block =>
      block.type === 'text'
  );


const nonEmptyTextBlocks =
  textBlocks.filter(
    block =>
      !block.is_empty
  );


const tableBlocks =
  blocks.filter(
    block =>
      block.type === 'table'
  );


const pictureBlocks =
  blocks.filter(
    block =>
      block.type === 'picture'
  );


const keyValueBlocks =
  blocks.filter(
    block =>
      block.type === 'key_value'
  );


const formBlocks =
  blocks.filter(
    block =>
      block.type === 'form_item'
  );


const textCharacters =
  textBlocks.reduce(
    (sum, block) =>
      sum +
      (block.text?.length ?? 0),
    0
  );


const tableCharacters =
  tableBlocks.reduce(
    (sum, block) => {
      const cells =
        block.table?.cells ??
        [];

      return sum +
        cells.reduce(
          (cellSum, cell) =>
            cellSum +
            (cell.text?.length ?? 0),
          0
        );
    },
    0
  );


const tableCellsCount =
  tableBlocks.reduce(
    (sum, block) =>
      sum +
      (
        block.table?.cells?.length ??
        0
      ),
    0
  );


// ============================================================
// 10. КОЛИЧЕСТВО СТРАНИЦ
// ============================================================

let pagesCount = 0;

if (Array.isArray(doc.pages)) {
  pagesCount =
    doc.pages.length;
}
else if (
  doc.pages &&
  typeof doc.pages === 'object'
) {
  pagesCount =
    Object.keys(doc.pages).length;
}


// ============================================================
// 11. ПРОВЕРКА ПОТЕРЬ ПРИ НОРМАЛИЗАЦИИ
// ============================================================

function buildRefs(collectionName, array) {
  if (!Array.isArray(array)) {
    return [];
  }

  return array.map(
    (_, index) =>
      `#/${collectionName}/${index}`
  );
}


const rawContentRefs = [
  ...buildRefs(
    'texts',
    collections.texts
  ),

  ...buildRefs(
    'tables',
    collections.tables
  ),

  ...buildRefs(
    'pictures',
    collections.pictures
  ),

  ...buildRefs(
    'key_value_items',
    collections.key_value_items
  ),

  ...buildRefs(
    'form_items',
    collections.form_items
  ),
];


const unvisitedContentRefs =
  rawContentRefs.filter(
    ref =>
      !visitedRefs.has(ref)
  );


const totalRawContentRefs =
  rawContentRefs.length;


const visitedContentRefs =
  totalRawContentRefs -
  unvisitedContentRefs.length;


const coverage =
  totalRawContentRefs > 0
    ? Number(
        (
          visitedContentRefs /
          totalRawContentRefs
        ).toFixed(4)
      )
    : 1;


// ============================================================
// 12. ИСХОДНЫЕ МЕТАДАННЫЕ ТЕНДЕРА / ДОКУМЕНТА
// ============================================================
//
// Пытаемся вернуть контекст,
// который был до скачивания JSON Docling.

let sourceContext = {};


try {
  sourceContext =
    $('Подготовить результат Docling').item.json;
}
catch (error) {
  // Нода может называться иначе
  // либо связь item временно отсутствует.
}


if (
  !sourceContext ||
  Object.keys(sourceContext).length === 0
) {
  try {
    sourceContext =
      $('Связать метаданные и файл').item.json;
  }
  catch (error) {
    sourceContext = {};
  }
}


// ============================================================
// 13. ФИНАЛЬНЫЙ УНИВЕРСАЛЬНЫЙ ФОРМАТ
// ============================================================

return {
  json: {

    analysis_run_id:
  sourceContext.analysis_run_id ??
  null,

    // --------------------------------------------------------
    // НАШИ ДАННЫЕ ТЕНДЕРА
    // --------------------------------------------------------

    tender_meta:
      sourceContext.tender_meta ??
      null,


    // --------------------------------------------------------
    // НАШИ ДАННЫЕ ДОКУМЕНТА
    // --------------------------------------------------------

    document:
      sourceContext.document ??
      {
        file_name:
          doc.origin?.filename ??
          null,

        mime_type:
          doc.origin?.mimetype ??
          null,
      },


    // --------------------------------------------------------
    // ИНФОРМАЦИЯ О ПАРСЕРЕ
    // --------------------------------------------------------

    parser: {
      provider: 'docling',

      schema:
        doc.schema_name ??
        null,

      schema_version:
        doc.version ??
        null,

      document_name:
        doc.name ??
        null,

      origin: {
        filename:
          doc.origin?.filename ??
          null,

        mimetype:
          doc.origin?.mimetype ??
          null,

        binary_hash:
          doc.origin?.binary_hash ??
          null,
      },
    },


    // --------------------------------------------------------
    // СТАТИСТИКА ДОКУМЕНТА
    // --------------------------------------------------------

    structure: {
      pages_count:
        pagesCount,

      groups_count:
        collections.groups.length,

      blocks_count:
        blocks.length,

      text_blocks_count:
        textBlocks.length,

      non_empty_text_blocks_count:
        nonEmptyTextBlocks.length,

      table_blocks_count:
        tableBlocks.length,

      picture_blocks_count:
        pictureBlocks.length,

      key_value_blocks_count:
        keyValueBlocks.length,

      form_blocks_count:
        formBlocks.length,

      table_cells_count:
        tableCellsCount,

      text_characters:
        textCharacters,

      table_characters:
        tableCharacters,

      total_content_characters:
        textCharacters +
        tableCharacters,
    },


    // --------------------------------------------------------
    // КОНТРОЛЬ КАЧЕСТВА НОРМАЛИЗАЦИИ
    // --------------------------------------------------------

    normalization_quality: {

      raw_docling: {
        texts_count:
          collections.texts.length,

        tables_count:
          collections.tables.length,

        pictures_count:
          collections.pictures.length,

        groups_count:
          collections.groups.length,

        key_value_items_count:
          collections.key_value_items.length,

        form_items_count:
          collections.form_items.length,

        total_content_elements:
          totalRawContentRefs,
      },


      normalized: {
        text_blocks_count:
          textBlocks.length,

        table_blocks_count:
          tableBlocks.length,

        picture_blocks_count:
          pictureBlocks.length,

        key_value_blocks_count:
          keyValueBlocks.length,

        form_blocks_count:
          formBlocks.length,

        total_blocks_count:
          blocks.length,
      },


      visited_refs_count:
        visitedRefs.size,

      unknown_refs_count:
        unknownRefs.length,

      unknown_refs:
        unknownRefs,

      unvisited_content_refs_count:
        unvisitedContentRefs.length,

      unvisited_content_refs:
        unvisitedContentRefs,

      coverage,
    },


    // --------------------------------------------------------
    // ГЛАВНЫЙ КОНТЕНТ ДОКУМЕНТА
    // --------------------------------------------------------

    blocks,
  },
};

// ============================================================
// ПОДГОТОВИТЬ БЛОКИ К АНАЛИЗУ
//
// Что делает:
// 1. Ничего не удаляет из исходного набора blocks.
// 2. Помечает блоки, которые не надо отправлять в AI.
// 3. Для простых страниц PDF восстанавливает порядок сверху вниз.
// 4. Сложные / многоколоночные страницы не переставляет автоматически.
// 5. Сохраняет исходный order и добавляет analysis_order.
// ============================================================

const items = $input.all();


// ------------------------------------------------------------
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ------------------------------------------------------------

function getPageNo(block) {
  const pageNo = block?.source?.page_no;

  return Number.isFinite(pageNo)
    ? pageNo
    : null;
}


function getBBox(block) {
  const bbox = block?.source?.bbox;

  if (
    !bbox ||
    !Number.isFinite(bbox.l) ||
    !Number.isFinite(bbox.r) ||
    !Number.isFinite(bbox.t) ||
    !Number.isFinite(bbox.b)
  ) {
    return null;
  }

  return bbox;
}


function getBoxGeometry(block) {
  const bbox = getBBox(block);

  if (!bbox) {
    return null;
  }

  const xMin = Math.min(bbox.l, bbox.r);
  const xMax = Math.max(bbox.l, bbox.r);
  const yMin = Math.min(bbox.t, bbox.b);
  const yMax = Math.max(bbox.t, bbox.b);

  return {
    xMin,
    xMax,
    yMin,
    yMax,
    width: Math.max(0, xMax - xMin),
    height: Math.max(0, yMax - yMin),
    coordOrigin: bbox.coord_origin ?? null,
  };
}


function tableHasContent(block) {
  const cells = block?.table?.cells;

  if (!Array.isArray(cells)) {
    return false;
  }

  return cells.some(cell => {
    return String(cell?.text ?? '').trim().length > 0;
  });
}


// ------------------------------------------------------------
// СТАТИСТИКА СТРАНИЦЫ
//
// Нужна, например, чтобы определить номер страницы внизу,
// даже если Docling случайно назвал его обычным text.
// ------------------------------------------------------------

function buildPageStats(pageBlocks) {
  const geometries = pageBlocks
    .map(getBoxGeometry)
    .filter(Boolean);

  if (geometries.length === 0) {
    return null;
  }

  return {
    minX: Math.min(...geometries.map(g => g.xMin)),
    maxX: Math.max(...geometries.map(g => g.xMax)),
    minY: Math.min(...geometries.map(g => g.yMin)),
    maxY: Math.max(...geometries.map(g => g.yMax)),
  };
}


// ------------------------------------------------------------
// ПОХОЖ ЛИ БЛОК НА НОМЕР СТРАНИЦЫ
//
// Например:
// page_no = 4
// text = "4"
// bbox находится почти в самом низу страницы.
//
// Это позволит убрать тот случай, который мы уже встретили,
// когда Docling не поставил label = page_footer.
// ------------------------------------------------------------

function isLikelyPageNumber(block, pageStats) {
  if (!pageStats || block?.type !== 'text') {
    return false;
  }

  const pageNo = getPageNo(block);

  if (pageNo === null) {
    return false;
  }

  const text = String(block?.text ?? '').trim();

  if (text !== String(pageNo)) {
    return false;
  }

  const geometry = getBoxGeometry(block);

  if (!geometry) {
    return false;
  }

  const origin = geometry.coordOrigin;

  // Для обычных PDF Docling у нас сейчас использует BOTTOMLEFT:
  // 0 находится внизу страницы.
  if (origin === 'BOTTOMLEFT') {
    const estimatedHeight = Math.max(pageStats.maxY, 1);

    return geometry.yMax <= estimatedHeight * 0.12;
  }

  // На случай TOPLEFT:
  // координата растёт сверху вниз.
  if (origin === 'TOPLEFT') {
    const estimatedBottom = Math.max(pageStats.maxY, 1);

    return geometry.yMin >= estimatedBottom * 0.88;
  }

  return false;
}


// ------------------------------------------------------------
// РЕШЕНИЕ: НУЖЕН ЛИ БЛОК ДЛЯ ТЕКСТОВОГО AI-АНАЛИЗА
//
// ВАЖНО:
// блок НЕ удаляется.
// Мы только ставим include = false.
// ------------------------------------------------------------

function classifyBlock(block, pageStats) {
  // Пустой текст
  if (
    block?.type === 'text' &&
    String(block?.text ?? '').trim() === ''
  ) {
    return {
      include: false,
      reason: 'empty_text',
    };
  }

  // Нижний колонтитул / номер страницы.
  // Его можно безопасно исключать из анализа.
  //
  // ВАЖНО:
  // page_header и content_layer = furniture
  // автоматически НЕ исключаем.
  //
  // Docling иногда ошибочно помечает смысловой текст
  // как page_header / furniture.
  // Например: "Приложение № 4 к Договору".
  if (block?.label === 'page_footer') {
    return {
      include: false,
      reason: 'page_footer',
    };
  }

  // Номер страницы, который Docling ошибочно назвал обычным текстом
  if (isLikelyPageNumber(block, pageStats)) {
    return {
      include: false,
      reason: 'probable_page_number',
    };
  }

  // Пустая таблица
  if (
    block?.type === 'table' &&
    !tableHasContent(block)
  ) {
    return {
      include: false,
      reason: 'empty_table',
    };
  }

  // Картинка пока не имеет собственного текста для AI.
  // Сам блок при этом сохраняем.
  if (block?.type === 'picture') {
    return {
      include: false,
      reason: 'visual_content',
    };
  }

  return {
    include: true,
    reason: null,
  };
}


// ------------------------------------------------------------
// ПРОВЕРКА НА МНОГОКОЛОНОЧНУЮ / СЛОЖНУЮ СТРАНИЦУ
//
// Ищем несколько блоков, которые:
// - находятся примерно на одной высоте;
// - не пересекаются по горизонтали;
// - выглядят как две отдельные колонки.
//
// Если такая структура есть, страницу автоматически
// сверху вниз НЕ сортируем.
// ------------------------------------------------------------

function detectComplexPage(blocks) {
  const items = blocks
    .map(block => ({
      block,
      geometry: getBoxGeometry(block),
    }))
    .filter(item => item.geometry);

  if (items.length < 2) {
    return false;
  }

  const minX = Math.min(...items.map(i => i.geometry.xMin));
  const maxX = Math.max(...items.map(i => i.geometry.xMax));

  const pageWidth = Math.max(1, maxX - minX);

  let sideBySidePairs = 0;

  for (let i = 0; i < items.length; i++) {
    for (let j = i + 1; j < items.length; j++) {
      const a = items[i].geometry;
      const b = items[j].geometry;

      // Таблица считается одним самостоятельным блоком.
      // Внутренние колонки таблицы здесь не анализируем.
      if (
        items[i].block.type === 'table' ||
        items[j].block.type === 'table'
      ) {
        continue;
      }

      const overlapY = Math.max(
        0,
        Math.min(a.yMax, b.yMax) - Math.max(a.yMin, b.yMin)
      );

      const minHeight = Math.max(
        1,
        Math.min(a.height, b.height)
      );

      const verticalOverlapRatio = overlapY / minHeight;

      const separatedHorizontally =
        a.xMax < b.xMin ||
        b.xMax < a.xMin;

      const bothLookLikeColumns =
        a.width < pageWidth * 0.72 &&
        b.width < pageWidth * 0.72;

      if (
        verticalOverlapRatio >= 0.4 &&
        separatedHorizontally &&
        bothLookLikeColumns
      ) {
        sideBySidePairs++;

        // Одной случайной пары мало.
        // Две и более уже считаем признаком сложной разметки.
        if (sideBySidePairs >= 2) {
          return true;
        }
      }
    }
  }

  return false;
}


// ------------------------------------------------------------
// СОРТИРОВКА ПРОСТОЙ PDF-СТРАНИЦЫ
// ------------------------------------------------------------

function sortPageVisually(blocks) {
  return [...blocks].sort((a, b) => {
    const boxA = getBBox(a);
    const boxB = getBBox(b);

    if (!boxA && !boxB) {
      return (a.order ?? 0) - (b.order ?? 0);
    }

    if (!boxA) return 1;
    if (!boxB) return -1;

    const origin =
      boxA.coord_origin ??
      boxB.coord_origin ??
      'BOTTOMLEFT';

    // PDF Docling: сверху страницы t больше.
    if (origin === 'BOTTOMLEFT') {
      const vertical = boxB.t - boxA.t;

      if (Math.abs(vertical) > 2) {
        return vertical;
      }

      return boxA.l - boxB.l;
    }

    // Если координаты идут сверху вниз.
    if (origin === 'TOPLEFT') {
      const vertical = boxA.t - boxB.t;

      if (Math.abs(vertical) > 2) {
        return vertical;
      }

      return boxA.l - boxB.l;
    }

    return (a.order ?? 0) - (b.order ?? 0);
  });
}


// ============================================================
// ОБРАБОТКА КАЖДОГО ДОКУМЕНТА
// ============================================================

return items.map((item, itemIndex) => {
  const input = item.json ?? {};

  const sourceBlocks = Array.isArray(input.blocks)
    ? input.blocks
    : [];

  const extension = String(
    input?.document?.file_extension ?? ''
  ).toLowerCase();

  const mimetype = String(
    input?.parser?.origin?.mimetype ?? ''
  ).toLowerCase();

  const isPdf =
    extension === 'pdf' ||
    mimetype === 'application/pdf';


  // ----------------------------------------------------------
  // ГРУППИРУЕМ БЛОКИ ПО СТРАНИЦАМ
  // ----------------------------------------------------------

  const pageMap = new Map();

  for (const block of sourceBlocks) {
    const pageNo = getPageNo(block);

    if (pageNo === null) {
      continue;
    }

    if (!pageMap.has(pageNo)) {
      pageMap.set(pageNo, []);
    }

    pageMap.get(pageNo).push(block);
  }


  // ----------------------------------------------------------
  // СТАТИСТИКА СТРАНИЦ
  // ----------------------------------------------------------

  const pageStatsMap = new Map();

  for (const [pageNo, blocks] of pageMap.entries()) {
    pageStatsMap.set(
      pageNo,
      buildPageStats(blocks)
    );
  }


  // ----------------------------------------------------------
  // ПОМЕЧАЕМ ВСЕ БЛОКИ
  // ----------------------------------------------------------

  const decisions = new Map();

  for (const block of sourceBlocks) {
    const pageNo = getPageNo(block);
    const pageStats = pageStatsMap.get(pageNo) ?? null;

    decisions.set(
      block.block_id,
      classifyBlock(block, pageStats)
    );
  }


  // ----------------------------------------------------------
  // СОЗДАЁМ ПОРЯДОК ДЛЯ АНАЛИЗА
  // ----------------------------------------------------------

  let orderedAnalysisBlocks = [];
  const pageSummaries = [];
  const warnings = [];

  if (isPdf) {
    const pageNumbers = [...pageMap.keys()]
      .sort((a, b) => a - b);

    for (const pageNo of pageNumbers) {
      const pageBlocks = pageMap.get(pageNo) ?? [];

      const includedBlocks = pageBlocks.filter(block => {
        return decisions.get(block.block_id)?.include === true;
      });

      const complexPage = detectComplexPage(includedBlocks);

      let orderedPageBlocks;
      let orderMethod;

      if (complexPage) {
        // Сложную страницу не ломаем.
        // Оставляем порядок, который пришёл из normalizer.
        orderedPageBlocks = [...includedBlocks]
          .sort((a, b) => {
            return (a.order ?? 0) - (b.order ?? 0);
          });

        orderMethod = 'original';

        warnings.push({
          type: 'complex_page_layout',
          page_no: pageNo,
          message:
            'На странице обнаружена сложная или многоколоночная разметка. Автоматическая перестановка блоков не выполнялась.',
        });
      } else {
        orderedPageBlocks = sortPageVisually(includedBlocks);
        orderMethod = 'visual';
      }

      const originalIds = [...includedBlocks]
        .sort((a, b) => {
          return (a.order ?? 0) - (b.order ?? 0);
        })
        .map(block => block.block_id);

      const preparedIds = orderedPageBlocks
        .map(block => block.block_id);

      const orderChanged =
        JSON.stringify(originalIds) !==
        JSON.stringify(preparedIds);

      pageSummaries.push({
        page_no: pageNo,
        blocks_count: pageBlocks.length,
        included_blocks_count: includedBlocks.length,
        excluded_blocks_count:
          pageBlocks.length - includedBlocks.length,
        complex_layout: complexPage,
        order_method: orderMethod,
        order_changed: orderChanged,
      });

      orderedAnalysisBlocks.push(...orderedPageBlocks);
    }


    // На всякий случай:
    // если в PDF встретились блоки без номера страницы,
    // не теряем их и добавляем после остальных
    // в исходном порядке.
    const noPageBlocks = sourceBlocks
      .filter(block => {
        return (
          getPageNo(block) === null &&
          decisions.get(block.block_id)?.include === true
        );
      })
      .sort((a, b) => {
        return (a.order ?? 0) - (b.order ?? 0);
      });

    orderedAnalysisBlocks.push(...noPageBlocks);

    if (noPageBlocks.length > 0) {
      warnings.push({
        type: 'blocks_without_page',
        count: noPageBlocks.length,
        message:
          'В PDF есть блоки без номера страницы. Для них сохранён исходный порядок.',
      });
    }

  } else {
    // DOCX / XLSX и остальные форматы:
    // координаты страниц использовать нельзя как универсальный
    // источник порядка, поэтому сохраняем исходный порядок.
    orderedAnalysisBlocks = sourceBlocks
      .filter(block => {
        return decisions.get(block.block_id)?.include === true;
      })
      .sort((a, b) => {
        return (a.order ?? 0) - (b.order ?? 0);
      });
  }


  // ----------------------------------------------------------
  // НАЗНАЧАЕМ analysis_order
  // ----------------------------------------------------------

  const analysisOrderMap = new Map();

  orderedAnalysisBlocks.forEach((block, index) => {
    analysisOrderMap.set(
      block.block_id,
      index + 1
    );
  });


  // ----------------------------------------------------------
  // СОХРАНЯЕМ ВСЕ ИСХОДНЫЕ БЛОКИ
  // + добавляем служебную информацию для анализа
  // ----------------------------------------------------------

  const preparedBlocks = sourceBlocks.map(block => {
    const decision =
      decisions.get(block.block_id) ?? {
        include: false,
        reason: 'unknown',
      };

    return {
      ...block,

      analysis: {
        include: decision.include,
        exclude_reason: decision.reason,
        analysis_order:
          analysisOrderMap.get(block.block_id) ?? null,
      },
    };
  });


  // ----------------------------------------------------------
  // КОНТРОЛЬ: НИ ОДИН БЛОК НЕ ДОЛЖЕН ПРОПАСТЬ
  // ----------------------------------------------------------

  if (preparedBlocks.length !== sourceBlocks.length) {
    throw new Error(
      `Подготовка блоков потеряла данные: вход=${sourceBlocks.length}, выход=${preparedBlocks.length}`
    );
  }


  const includedCount =
    preparedBlocks.filter(
      block => block.analysis.include
    ).length;

  const excludedCount =
    preparedBlocks.length - includedCount;


  const pagesWithChangedOrder =
    pageSummaries
      .filter(page => page.order_changed)
      .map(page => page.page_no);


  // Небольшой список block_id в нужном порядке.
  // Следующий этап сможет быстро восстановить
  // подготовленную последовательность.
  const analysisSequence =
    orderedAnalysisBlocks.map(
      block => block.block_id
    );


  return {
    json: {
      ...input,

      blocks: preparedBlocks,

      analysis_preparation: {
        version: '1.0',

        source_blocks_count: sourceBlocks.length,
        prepared_blocks_count: preparedBlocks.length,

        included_blocks_count: includedCount,
        excluded_blocks_count: excludedCount,

        data_loss: false,

        pages_with_changed_order:
          pagesWithChangedOrder,

        pages: pageSummaries,

        warnings,
      },

      analysis_sequence: analysisSequence,
    },

    pairedItem: {
      item: itemIndex,
    },
  };
});

// ============================================================
// ПОДГОТОВИТЬ ЧАСТИ ДЛЯ АНАЛИЗА v1.3
//
// Вход:
// - semantic_blocks[]
// - sections[]
// - spreadsheet_context (для XLSX)
//
// Выход:
// - analysis_units[]
// - analysis_unit_building
//
// Дополнительно в v1.3:
// 1. Разные Excel-листы никогда не смешиваются в одной analysis_unit.
// 2. Каждая XLSX-часть получает sheet_name + sheet_title.
// 3. Заголовок листа не дублируется в контексте, если он уже есть
//    в primary_text этой же части.
// 4. Таблицы по-прежнему никогда не используются как overlap.
// ============================================================

const items = $input.all();


const CONFIG = {

  // Это приблизительная оценка, а не настоящий tokenizer модели.
  //
  // Для русского текста берём консервативно:
  // примерно 3 символа = 1 токен.
  approxCharsPerToken: 3.0,


  // Для текущего стресс-теста оставляем 600.
  //
  // После окончания стресс-тестов нужно вернуть
  // production-значение 3200.
  maxPrimaryApproxTokens: 3200,


  // Если один подраздел пришлось разрезать,
  // следующей части повторяем последний смысловой блок
  // предыдущей части как контекст.
  overlapSemanticBlocks: 1,
};


// ------------------------------------------------------------
// ОБЩИЕ ФУНКЦИИ
// ------------------------------------------------------------

function uniq(values) {

  return [
    ...new Set(
      values.filter(
        value =>
          value !== null &&
          value !== undefined
      )
    ),
  ];
}


function normalizeInline(text) {

  return String(text ?? '')
    .replace(/\u00A0/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .trim();
}


function normalizeMultiline(text) {

  return String(text ?? '')
    .replace(/\u00A0/g, ' ')
    .split('\n')
    .map(line =>
      line
        .replace(/[ \t]+/g, ' ')
        .trim()
    )
    .filter((line, index, arr) => {

      if (line !== '') {
        return true;
      }

      return (
        index > 0 &&
        arr[index - 1] !== ''
      );
    })
    .join('\n')
    .trim();
}


function blockText(block) {

  return normalizeMultiline(
    block?.text ?? ''
  );
}


// ------------------------------------------------------------
// XLSX: ИМЯ ЛИСТА
// ------------------------------------------------------------

function getSheetName(block) {

  return (
    normalizeInline(
      block?.sheet_name ?? ''
    ) ||
    null
  );
}


function getSheetNames(blocks) {

  return uniq(
    blocks
      .map(
        getSheetName
      )
      .filter(Boolean)
  );
}


// ------------------------------------------------------------
// ПРИБЛИЗИТЕЛЬНАЯ ОЦЕНКА ТОКЕНОВ
// ------------------------------------------------------------

function estimateTokensFromText(text) {

  const characters =
    String(text ?? '').length;


  return Math.ceil(
    characters /
    CONFIG.approxCharsPerToken
  );
}


function estimateBlocksTokens(blocks) {

  return blocks.reduce(
    (sum, block) => {

      return (
        sum +
        estimateTokensFromText(
          blockText(block)
        )
      );

    },
    0
  );
}


// ------------------------------------------------------------
// ПОЛУЧАЕМ ПОДРАЗДЕЛ ИЗ section_path
//
// [
//   "Статья 5. Права и обязанности Сторон",
//   "5.3. Поставщик вправе:"
// ]
//
// → "5.3. Поставщик вправе:"
// ------------------------------------------------------------

function getSubsectionTitle(block) {

  const path =
    Array.isArray(
      block?.section_path
    )
      ? block.section_path
      : [];


  if (
    path.length >= 2
  ) {

    return (
      normalizeInline(
        path[1]
      ) ||
      null
    );
  }


  return null;
}


// ------------------------------------------------------------
// СПИСОК ПОДРАЗДЕЛОВ
// ------------------------------------------------------------

function getSubsectionTitles(blocks) {

  const titles = [];


  for (
    const block
    of blocks
  ) {

    const title =
      getSubsectionTitle(
        block
      );


    if (title) {
      titles.push(title);
    }
  }


  return uniq(titles);
}


// ------------------------------------------------------------
// ПЕРВЫЙ ПОДРАЗДЕЛ ЧАСТИ
// ------------------------------------------------------------

function firstMeaningfulSubsection(blocks) {

  for (
    const block
    of blocks
  ) {

    if (
      block?.role ===
      'section_heading'
    ) {
      continue;
    }


    return getSubsectionTitle(
      block
    );
  }


  return null;
}


// ------------------------------------------------------------
// ПОСЛЕДНИЙ ПОДРАЗДЕЛ ЧАСТИ
// ------------------------------------------------------------

function lastMeaningfulSubsection(blocks) {

  for (
    let i = blocks.length - 1;
    i >= 0;
    i--
  ) {

    const block =
      blocks[i];


    if (
      block?.role ===
      'section_heading'
    ) {
      continue;
    }


    return getSubsectionTitle(
      block
    );
  }


  return null;
}


// ------------------------------------------------------------
// СТРАНИЦЫ
// ------------------------------------------------------------

function getPageNumbers(blocks) {

  const pages = [];


  for (
    const block
    of blocks
  ) {

    if (
      Array.isArray(
        block?.source_pages
      )
    ) {

      for (
        const page
        of block.source_pages
      ) {

        if (
          Number.isFinite(page)
        ) {
          pages.push(page);
        }
      }
    }


    if (
      Number.isFinite(
        block?.page_from
      )
    ) {

      pages.push(
        block.page_from
      );
    }


    if (
      Number.isFinite(
        block?.page_to
      )
    ) {

      pages.push(
        block.page_to
      );
    }
  }


  return uniq(pages)
    .sort(
      (a, b) =>
        a - b
    );
}


// ------------------------------------------------------------
// ИСХОДНЫЕ block_id
// ------------------------------------------------------------

function getSourceBlockIds(blocks) {

  const ids = [];


  for (
    const block
    of blocks
  ) {

    const blockIds =
      Array.isArray(
        block?.source_block_ids
      )
        ? block.source_block_ids
        : [];


    ids.push(
      ...blockIds
    );
  }


  return uniq(ids);
}


// ------------------------------------------------------------
// ЕСТЬ ЛИ ТАБЛИЦА
// ------------------------------------------------------------

function containsTable(blocks) {

  return blocks.some(
    block =>
      block?.type ===
      'table'
  );
}


function tableSemanticBlockIds(blocks) {

  return blocks
    .filter(
      block =>
        block?.type ===
        'table'
    )
    .map(
      block =>
        block.semantic_block_id
    );
}


// ============================================================
// СОБИРАЕМ ЛОГИЧЕСКИЕ ГРУППЫ
//
// ВАЖНО v1.3:
//
// Смена sheet_name ВСЕГДА начинает новую группу.
//
// Поэтому:
//
// Лист1
//   блок A
//   блок B
//
// Лист2
//   блок C
//
// никогда не станут одной логической группой.
// ============================================================

function buildLogicalGroups(
  sectionBlocks
) {

  const groups = [];

  let current = null;


  function startGroup(
    subsectionTitle,
    sheetName
  ) {

    current = {

      subsection_title:
        subsectionTitle ??
        null,

      sheet_name:
        sheetName ??
        null,

      blocks: [],
    };


    groups.push(
      current
    );
  }


  for (
    const block
    of sectionBlocks
  ) {

    const subsectionTitle =
      getSubsectionTitle(
        block
      );


    const sheetName =
      getSheetName(
        block
      );


    const startsNewSubsection =
      block?.role ===
      'subsection_heading';


    if (!current) {

      startGroup(
        subsectionTitle,
        sheetName
      );
    }


    // --------------------------------------------------------
    // XLSX:
    // НОВЫЙ ЛИСТ = ОБЯЗАТЕЛЬНО НОВАЯ ГРУППА
    // --------------------------------------------------------

    else if (
      sheetName !==
      current.sheet_name
    ) {

      startGroup(
        subsectionTitle,
        sheetName
      );
    }


    else if (
      startsNewSubsection
    ) {

      startGroup(
        subsectionTitle,
        sheetName
      );
    }


    else if (
      subsectionTitle !==
        current.subsection_title &&
      subsectionTitle !== null
    ) {

      startGroup(
        subsectionTitle,
        sheetName
      );
    }


    current.blocks.push(
      block
    );
  }


  return groups;
}


// ============================================================
// ЕСЛИ ОДНА ГРУППА СЛИШКОМ БОЛЬШАЯ
//
// Режем только между semantic_blocks.
// Один semantic_block / таблицу посередине не режем.
// ============================================================

function splitOversizedGroup(
  group,
  warnings,
  section
) {

  const maxTokens =
    CONFIG.maxPrimaryApproxTokens;


  const groupTokens =
    estimateBlocksTokens(
      group.blocks
    );


  // Всё помещается.
  if (
    groupTokens <=
    maxTokens
  ) {

    return [
      {

        subsection_title:
          group.subsection_title,

        sheet_name:
          group.sheet_name ??
          null,

        blocks:
          [...group.blocks],

        oversized_atomic_block:
          false,
      },
    ];
  }


  const pieces = [];

  let currentBlocks = [];
  let currentTokens = 0;


  function flush() {

    if (
      currentBlocks.length === 0
    ) {
      return;
    }


    pieces.push({

      subsection_title:
        group.subsection_title,

      sheet_name:
        group.sheet_name ??
        null,

      blocks:
        currentBlocks,

      oversized_atomic_block:
        false,
    });


    currentBlocks = [];
    currentTokens = 0;
  }


  for (
    const block
    of group.blocks
  ) {

    const tokens =
      estimateTokensFromText(
        blockText(block)
      );


    // --------------------------------------------------------
    // Один semantic_block сам больше лимита.
    //
    // НЕ режем его посередине.
    // --------------------------------------------------------

    if (
      tokens >
      maxTokens
    ) {

      flush();


      pieces.push({

        subsection_title:
          group.subsection_title,

        sheet_name:
          group.sheet_name ??
          null,

        blocks: [
          block,
        ],

        oversized_atomic_block:
          true,
      });


      warnings.push({

        type:
          'oversized_atomic_semantic_block',

        section_id:
          section.section_id,

        section_title:
          section.title,

        sheet_name:
          group.sheet_name ??
          null,

        semantic_block_id:
          block.semantic_block_id,

        approx_tokens:
          tokens,

        message:
          'Один смысловой блок сам превышает лимит. Он оставлен целиком, чтобы не разрезать смысл или таблицу посередине.',
      });


      continue;
    }


    if (
      currentBlocks.length > 0 &&
      currentTokens + tokens >
      maxTokens
    ) {

      flush();
    }


    currentBlocks.push(
      block
    );


    currentTokens +=
      tokens;
  }


  flush();


  return pieces;
}


// ============================================================
// СОБИРАЕМ PIECES В ANALYSIS UNITS
//
// ВАЖНО v1.3:
//
// pieces с разными sheet_name
// НИКОГДА не объединяются.
// ============================================================

function packSectionPieces(
  pieces
) {

  const maxTokens =
    CONFIG.maxPrimaryApproxTokens;


  const units = [];


  let currentBlocks = [];
  let currentTokens = 0;
  let currentOversized = false;
  let currentSheetName = null;


  function flush() {

    if (
      currentBlocks.length === 0
    ) {
      return;
    }


    units.push({

      primary_blocks:
        currentBlocks,

      sheet_name:
        currentSheetName,

      oversized_atomic_block:
        currentOversized,
    });


    currentBlocks = [];
    currentTokens = 0;
    currentOversized = false;
    currentSheetName = null;
  }


  for (
    const piece
    of pieces
  ) {

    const pieceTokens =
      estimateBlocksTokens(
        piece.blocks
      );


    const pieceSheetName =
      piece.sheet_name ??
      null;


    const sheetChanged =
      currentBlocks.length > 0 &&
      currentSheetName !==
      pieceSheetName;


    const wouldExceedLimit =
      currentBlocks.length > 0 &&
      currentTokens + pieceTokens >
      maxTokens;


    // --------------------------------------------------------
    // Либо закончился лимит,
    // либо начался новый Excel-лист.
    // --------------------------------------------------------

    if (
      sheetChanged ||
      wouldExceedLimit
    ) {

      flush();
    }


    if (
      currentBlocks.length === 0
    ) {

      currentSheetName =
        pieceSheetName;
    }


    currentBlocks.push(
      ...piece.blocks
    );


    currentTokens +=
      pieceTokens;


    currentOversized =
      currentOversized ||
      piece.oversized_atomic_block ===
        true;
  }


  flush();


  return units;
}


// ============================================================
// ФОРМИРУЕМ ГОТОВЫЙ ТЕКСТ ДЛЯ НЕЙРОНКИ
// ============================================================

function buildAnalysisText(unit) {

  const lines = [];


  // ----------------------------------------------------------
  // ОБЩИЙ КОНТЕКСТ
  // ----------------------------------------------------------

  lines.push(
    'КОНТЕКСТ ДОКУМЕНТА'
  );


  lines.push(
    `Раздел: ${unit.section_title}`
  );


  // ----------------------------------------------------------
  // XLSX-КОНТЕКСТ
  // ----------------------------------------------------------

  if (
    unit.context
      .sheet_name
  ) {

    lines.push(
      `Excel-лист: ${unit.context.sheet_name}`
    );
  }


  // ----------------------------------------------------------
  // Заголовок листа повторяем как постоянный контекст,
  // НО только если этот semantic block не находится
  // непосредственно в primary_text текущей части.
  //
  // Иначе получили бы:
  //
  // Заголовок листа: ...
  //
  // ОСНОВНОЙ ТЕКСТ:
  // тот же самый заголовок...
  //
  // ----------------------------------------------------------

  if (
    unit.context
      .sheet_title &&

    !unit.context
      .sheet_title_in_primary
  ) {

    lines.push(
      `Заголовок листа: ${unit.context.sheet_title}`
    );
  }


  lines.push(
    `Часть раздела: ${unit.part_index} из ${unit.parts_total}`
  );


  // ----------------------------------------------------------
  // ПОДРАЗДЕЛЫ
  // ----------------------------------------------------------

  if (
    unit.context
      .subsection_titles
      .length > 0
  ) {

    lines.push(
      'Подразделы, встречающиеся в этой части:'
    );


    for (
      const title
      of unit.context
        .subsection_titles
    ) {

      lines.push(
        `- ${title}`
      );
    }
  }


  // ----------------------------------------------------------
  // OVERLAP
  // ----------------------------------------------------------

  if (
    unit.overlap_text
  ) {

    lines.push('');


    lines.push(
      'ПОВТОР ИЗ ПРЕДЫДУЩЕЙ ЧАСТИ — ТОЛЬКО ДЛЯ КОНТЕКСТА'
    );


    lines.push(
      unit.overlap_text
    );
  }


  // ----------------------------------------------------------
  // ОСНОВНОЙ ТЕКСТ
  // ----------------------------------------------------------

  lines.push('');


  lines.push(
    'ОСНОВНОЙ ТЕКСТ ЭТОЙ ЧАСТИ'
  );


  lines.push(
    unit.primary_text
  );


  return lines
    .join('\n')
    .trim();
}


// ============================================================
// ОБРАБОТКА ОДНОГО ДОКУМЕНТА
// ============================================================

function processDocument(input) {

  const semanticBlocks =
    Array.isArray(
      input.semantic_blocks
    )
      ? input.semantic_blocks
      : [];


  const sections =
    Array.isArray(
      input.sections
    )
      ? input.sections
      : [];


  // ----------------------------------------------------------
  // XLSX:
  // создаём быстрый справочник:
  //
  // "Лист1" → {
  //   sheet_title,
  //   title_semantic_block_id,
  //   ...
  // }
  // ----------------------------------------------------------

  const spreadsheetSheets =
    Array.isArray(
      input
        ?.spreadsheet_context
        ?.sheets
    )
      ? input.spreadsheet_context.sheets
      : [];


  const sheetContextByName =
    new Map();


  for (
    const sheet
    of spreadsheetSheets
  ) {

    const sheetName =
      normalizeInline(
        sheet?.sheet_name ??
        ''
      );


    if (!sheetName) {
      continue;
    }


    sheetContextByName.set(
      sheetName,
      sheet
    );
  }


  const semanticById =
    new Map(
      semanticBlocks.map(
        block => [
          block.semantic_block_id,
          block,
        ]
      )
    );


  const warnings = [];

  const draftUnits = [];


  const documentIndex =
    input?.document
      ?.document_index ??
    'x';


  const docPrefix =
    `doc_${documentIndex}`;


  // ==========================================================
  // 1. ОБРАБАТЫВАЕМ КАЖДЫЙ КРУПНЫЙ РАЗДЕЛ ОТДЕЛЬНО
  // ==========================================================

  for (
    const section
    of sections
  ) {

    const sectionBlocks = [];


    const semanticIds =
      Array.isArray(
        section.semantic_block_ids
      )
        ? section.semantic_block_ids
        : [];


    // --------------------------------------------------------
    // Восстанавливаем блоки раздела
    // --------------------------------------------------------

    for (
      const semanticId
      of semanticIds
    ) {

      const block =
        semanticById.get(
          semanticId
        );


      if (!block) {

        warnings.push({

          type:
            'missing_semantic_block_in_section',

          section_id:
            section.section_id,

          semantic_block_id:
            semanticId,

          message:
            'Раздел ссылается на отсутствующий semantic_block.',
        });


        continue;
      }


      sectionBlocks.push(
        block
      );
    }


    if (
      sectionBlocks.length === 0
    ) {
      continue;
    }


    // --------------------------------------------------------
    // Сначала группируем по подразделам
    // И одновременно по Excel-листам.
    // --------------------------------------------------------

    const logicalGroups =
      buildLogicalGroups(
        sectionBlocks
      );


    // --------------------------------------------------------
    // Большие группы при необходимости режем.
    // --------------------------------------------------------

    const pieces = [];


    for (
      const group
      of logicalGroups
    ) {

      pieces.push(
        ...splitOversizedGroup(
          group,
          warnings,
          section
        )
      );
    }


    // --------------------------------------------------------
    // Собираем части.
    //
    // packSectionPieces уже гарантирует:
    // два разных sheet_name не смешаются.
    // --------------------------------------------------------

    const sectionUnits =
      packSectionPieces(
        pieces
      );


    for (
      const sectionUnit
      of sectionUnits
    ) {

      draftUnits.push({

        section_id:
          section.section_id,

        section_title:
          section.title,

        section_kind:
          section.kind ??
          'section',

        sheet_name:
          sectionUnit.sheet_name ??
          null,

        primary_blocks:
          sectionUnit.primary_blocks,

        oversized_atomic_block:
          sectionUnit
            .oversized_atomic_block ===
          true,
      });
    }
  }


  // ==========================================================
  // 2. ЗАЩИТА ОТ ПОТЕРЬ
  // ==========================================================

  const referencedPrimaryIds =
    new Set(
      draftUnits.flatMap(
        unit =>
          unit.primary_blocks.map(
            block =>
              block.semantic_block_id
          )
      )
    );


  const unassignedBlocks =
    semanticBlocks.filter(
      block =>
        !referencedPrimaryIds.has(
          block.semantic_block_id
        )
    );


  if (
    unassignedBlocks.length > 0
  ) {

    warnings.push({

      type:
        'semantic_blocks_without_section',

      count:
        unassignedBlocks.length,

      semantic_block_ids:
        unassignedBlocks.map(
          block =>
            block.semantic_block_id
        ),

      message:
        'Есть смысловые блоки, не привязанные ни к одному разделу. Они сохранены в отдельных технических частях.',
    });


    // --------------------------------------------------------
    // Даже fallback не имеет права смешивать
    // разные Excel-листы.
    // --------------------------------------------------------

    const fallbackBySheet =
      new Map();


    for (
      const block
      of unassignedBlocks
    ) {

      const sheetName =
        getSheetName(
          block
        );


      const key =
        sheetName ??
        '__NO_SHEET__';


      if (
        !fallbackBySheet.has(
          key
        )
      ) {

        fallbackBySheet.set(
          key,
          {

            sheet_name:
              sheetName,

            blocks: [],
          }
        );
      }


      fallbackBySheet
        .get(key)
        .blocks
        .push(
          block
        );
    }


    for (
      const fallback
      of fallbackBySheet.values()
    ) {

      draftUnits.push({

        section_id:
          'sec_unassigned',

        section_title:
          'Нераспределённые блоки',

        section_kind:
          'fallback',

        sheet_name:
          fallback.sheet_name,

        primary_blocks:
          fallback.blocks,

        oversized_atomic_block:
          false,
      });
    }
  }


  // ==========================================================
  // 3. PART INDEX / PARTS TOTAL
  //
  // ВАЖНО v1.3:
  //
  // Нумерацию частей считаем отдельно внутри:
  //
  // section_id + sheet_name
  //
  // То есть:
  //
  // Лист1 → часть 1 из 3
  // Лист1 → часть 2 из 3
  // Лист1 → часть 3 из 3
  //
  // Лист2 → часть 1 из 2
  // Лист2 → часть 2 из 2
  // ==========================================================

  const unitsByPartition =
    new Map();


  function getPartitionKey(unit) {

    return JSON.stringify([
      unit.section_id,
      unit.sheet_name ??
      null,
    ]);
  }


  for (
    const unit
    of draftUnits
  ) {

    const key =
      getPartitionKey(
        unit
      );


    if (
      !unitsByPartition.has(
        key
      )
    ) {

      unitsByPartition.set(
        key,
        []
      );
    }


    unitsByPartition
      .get(key)
      .push(
        unit
      );
  }


  for (
    const partitionUnits
    of unitsByPartition.values()
  ) {

    const total =
      partitionUnits.length;


    partitionUnits.forEach(
      (unit, index) => {

        unit.part_index =
          index + 1;

        unit.parts_total =
          total;
      }
    );
  }


  // ==========================================================
  // 4. OVERLAP
  //
  // Теперь он автоматически возможен только внутри:
  //
  // - того же крупного раздела;
  // - того же Excel-листа;
  // - того же подраздела.
  //
  // Таблицы overlap быть не могут.
  // ==========================================================

  for (
    const partitionUnits
    of unitsByPartition.values()
  ) {

    for (
      let i = 0;
      i < partitionUnits.length;
      i++
    ) {

      const unit =
        partitionUnits[i];


      unit.overlap_blocks = [];


      // Первая часть partition.
      if (
        i === 0
      ) {
        continue;
      }


      const previousUnit =
        partitionUnits[i - 1];


      const previousEndSubsection =
        lastMeaningfulSubsection(
          previousUnit.primary_blocks
        );


      const currentStartSubsection =
        firstMeaningfulSubsection(
          unit.primary_blocks
        );


      // ------------------------------------------------------
      // Разные подразделы → overlap не нужен.
      // ------------------------------------------------------

      if (
        previousEndSubsection !==
        currentStartSubsection
      ) {

        continue;
      }


      const overlapCount =
        Math.max(
          0,
          CONFIG.overlapSemanticBlocks
        );


      if (
        overlapCount === 0
      ) {

        continue;
      }


      // ------------------------------------------------------
      // Сначала берём реальные последние N блоков.
      //
      // Потом исключаем таблицы.
      //
      // Если последним блоком была таблица,
      // назад за старым текстом специально не идём.
      // ------------------------------------------------------

      const trailingCandidates =
        previousUnit
          .primary_blocks
          .filter(
            block =>
              block?.role !==
              'section_heading'
          )
          .slice(
            -overlapCount
          );


      const candidates =
        trailingCandidates
          .filter(
            block =>
              block?.type !==
              'table'
          );


      unit.overlap_blocks =
        candidates;
    }
  }


  // ==========================================================
  // 5. СОЗДАЁМ ФИНАЛЬНЫЕ analysis_units
  // ==========================================================

  const analysisUnits = [];

  let globalUnitIndex = 0;


  for (
    const draft
    of draftUnits
  ) {

    globalUnitIndex++;


    const primaryBlocks =
      draft.primary_blocks;


    const overlapBlocks =
      draft.overlap_blocks ??
      [];


    // --------------------------------------------------------
    // ДОПОЛНИТЕЛЬНАЯ ЗАЩИТА
    //
    // Если несмотря на предыдущую логику одна analysis_unit
    // каким-то образом содержит два разных Excel-листа —
    // останавливаем выполнение.
    //
    // Лучше упасть здесь, чем отправить модели неверный
    // контекст листа.
    // --------------------------------------------------------

    const primarySheetNames =
      getSheetNames(
        primaryBlocks
      );


    if (
      primarySheetNames.length > 1
    ) {

      throw new Error(
        `Analysis unit смешивает несколько Excel-листов: ${primarySheetNames.join(', ')}`
      );
    }


    const sheetName =
      draft.sheet_name ??
      primarySheetNames[0] ??
      null;


    // --------------------------------------------------------
    // НАХОДИМ КОНТЕКСТ XLSX-ЛИСТА
    // --------------------------------------------------------

    const sheetContext =
      sheetName

        ? (
            sheetContextByName.get(
              sheetName
            ) ??
            null
          )

        : null;


    const sheetTitle =
      normalizeInline(
        sheetContext
          ?.sheet_title ??
        ''
      ) ||
      null;


    const sheetTitleSemanticBlockId =
      sheetContext
        ?.title_semantic_block_id ??
      null;


    const sheetTitleSourceBlockId =
      sheetContext
        ?.title_source_block_id ??
      null;


    // --------------------------------------------------------
    // ОСНОВНОЙ ТЕКСТ
    // --------------------------------------------------------

    const primaryText =
      primaryBlocks
        .map(
          block =>
            blockText(block)
        )
        .filter(Boolean)
        .join('\n\n')
        .trim();


    // --------------------------------------------------------
    // OVERLAP
    // --------------------------------------------------------

    const overlapText =
      overlapBlocks
        .map(
          block =>
            blockText(block)
        )
        .filter(Boolean)
        .join('\n\n')
        .trim();


    // --------------------------------------------------------
    // ПОДРАЗДЕЛЫ
    // --------------------------------------------------------

    const subsectionTitles =
      getSubsectionTitles(
        primaryBlocks
      );


    // --------------------------------------------------------
    // semantic_block IDs
    // --------------------------------------------------------

    const primarySemanticBlockIds =
      primaryBlocks.map(
        block =>
          block.semantic_block_id
      );


    const overlapSemanticBlockIds =
      overlapBlocks.map(
        block =>
          block.semantic_block_id
      );


    // --------------------------------------------------------
    // SOURCE BLOCK IDs
    // --------------------------------------------------------

    const primarySourceBlockIds =
      getSourceBlockIds(
        primaryBlocks
      );


    const overlapSourceBlockIds =
      getSourceBlockIds(
        overlapBlocks
      );


    const allBlocks = [
      ...overlapBlocks,
      ...primaryBlocks,
    ];


    // --------------------------------------------------------
    // НАХОДИТСЯ ЛИ ЗАГОЛОВОК XLSX УЖЕ В PRIMARY
    //
    // Например Unit 1 содержит sb_0001:
    //
    // "Обоснование начальной максимальной цены..."
    //
    // Тогда отдельно повторять sheet_title в context
    // для текста модели не надо.
    // --------------------------------------------------------

    const sheetTitleInPrimary =
      sheetTitleSemanticBlockId !==
        null &&

      primarySemanticBlockIds
        .includes(
          sheetTitleSemanticBlockId
        );


    const unit = {

      analysis_unit_id:
        `${docPrefix}_au_${String(
          globalUnitIndex
        ).padStart(4, '0')}`,


      // ------------------------------------------------------
      // РАЗДЕЛ
      // ------------------------------------------------------

      section_id:
        draft.section_id,

      section_title:
        draft.section_title,

      section_kind:
        draft.section_kind,


      // ------------------------------------------------------
      // ЧАСТЬ
      // ------------------------------------------------------

      part_index:
        draft.part_index,

      parts_total:
        draft.parts_total,


      // ------------------------------------------------------
      // КОНТЕКСТ
      // ------------------------------------------------------

      context: {

        section_title:
          draft.section_title,


        subsection_titles:
          subsectionTitles,


        start_subsection_title:
          firstMeaningfulSubsection(
            primaryBlocks
          ),


        end_subsection_title:
          lastMeaningfulSubsection(
            primaryBlocks
          ),


        // ----------------------------------------------------
        // XLSX CONTEXT
        // ----------------------------------------------------

        sheet_name:
          sheetName,


        sheet_title:
          sheetTitle,


        sheet_title_semantic_block_id:
          sheetTitleSemanticBlockId,


        sheet_title_source_block_id:
          sheetTitleSourceBlockId,


        sheet_title_in_primary:
          sheetTitleInPrimary,
      },


      // ------------------------------------------------------
      // ТЕКСТ
      // ------------------------------------------------------

      primary_text:
        primaryText,


      overlap_text:
        overlapText ||
        null,


      // ------------------------------------------------------
      // SEMANTIC BLOCK IDs
      // ------------------------------------------------------

      primary_semantic_block_ids:
        primarySemanticBlockIds,


      overlap_semantic_block_ids:
        overlapSemanticBlockIds,


      // ------------------------------------------------------
      // SOURCE BLOCK IDs
      // ------------------------------------------------------

      primary_source_block_ids:
        primarySourceBlockIds,


      overlap_source_block_ids:
        overlapSourceBlockIds,


      // ------------------------------------------------------
      // СТРАНИЦЫ
      // ------------------------------------------------------

      source_pages:
        getPageNumbers(
          allBlocks
        ),


      // ------------------------------------------------------
      // РАЗМЕР
      // ------------------------------------------------------

      size: {

        primary_characters:
          primaryText.length,


        primary_approx_tokens:
          estimateTokensFromText(
            primaryText
          ),


        overlap_characters:
          overlapText.length,


        overlap_approx_tokens:
          overlapText

            ? estimateTokensFromText(
                overlapText
              )

            : 0,
      },


      // ------------------------------------------------------
      // ФЛАГИ
      // ------------------------------------------------------

      flags: {

        contains_table:
          containsTable(
            primaryBlocks
          ),


        table_semantic_block_ids:
          tableSemanticBlockIds(
            primaryBlocks
          ),


        oversized_atomic_block:
          draft
            .oversized_atomic_block ===
          true,


        contains_sheet_title_block:
          sheetTitleInPrimary,
      },
    };


    // --------------------------------------------------------
    // ГОТОВЫЙ ТЕКСТ ДЛЯ МОДЕЛИ
    // --------------------------------------------------------

    unit.analysis_text =
      buildAnalysisText(
        unit
      );


    unit.size
      .analysis_characters =
      unit.analysis_text.length;


    unit.size
      .analysis_approx_tokens =
      estimateTokensFromText(
        unit.analysis_text
      );


    analysisUnits.push(
      unit
    );
  }


  // ==========================================================
  // 6. КОНТРОЛЬ ПОТЕРЬ
  // ==========================================================

  const primaryUsage =
    new Map();


  for (
    const unit
    of analysisUnits
  ) {

    for (
      const semanticId
      of unit
        .primary_semantic_block_ids
    ) {

      primaryUsage.set(

        semanticId,

        (
          primaryUsage.get(
            semanticId
          ) ??
          0
        ) +
        1
      );
    }
  }


  const allSemanticIds =
    semanticBlocks.map(
      block =>
        block.semantic_block_id
    );


  const missingSemanticBlocks =
    allSemanticIds.filter(
      semanticId =>
        !primaryUsage.has(
          semanticId
        )
    );


  const duplicatedPrimarySemanticBlocks =
    [
      ...primaryUsage.entries(),
    ]
      .filter(
        ([, count]) =>
          count !== 1
      )
      .map(
        ([
          semantic_block_id,
          count,
        ]) => {

          return {
            semantic_block_id,
            count,
          };
        }
      );


  const primaryCoverage =
    allSemanticIds.length === 0

      ? 1

      : (
          allSemanticIds.length -
          missingSemanticBlocks.length
        ) /
        allSemanticIds.length;


  // ----------------------------------------------------------
  // PARTS > 3500
  // ----------------------------------------------------------

  const unitsOverRecommendedMax =
    analysisUnits
      .filter(
        unit =>
          unit.size
            .analysis_approx_tokens >
          3500
      )
      .map(
        unit => {

          return {

            analysis_unit_id:
              unit.analysis_unit_id,

            section_title:
              unit.section_title,

            sheet_name:
              unit.context
                .sheet_name,

            analysis_approx_tokens:
              unit.size
                .analysis_approx_tokens,

            oversized_atomic_block:
              unit.flags
                .oversized_atomic_block,
          };
        }
      );


  // ----------------------------------------------------------
  // СТАРАЯ МЕТРИКА split_sections_count
  //
  // Оставляем на уровне section_id,
  // чтобы не менять смысл существующего поля.
  // ----------------------------------------------------------

  const unitCountBySection =
    new Map();


  for (
    const unit
    of draftUnits
  ) {

    unitCountBySection.set(

      unit.section_id,

      (
        unitCountBySection.get(
          unit.section_id
        ) ??
        0
      ) +
      1
    );
  }


  const splitSectionsCount =
    [
      ...unitCountBySection.values(),
    ]
      .filter(
        count =>
          count > 1
      )
      .length;


  // ----------------------------------------------------------
  // Какие Excel-листы реально встретились в analysis_units
  // ----------------------------------------------------------

  const spreadsheetSheetNames =
    uniq(
      analysisUnits
        .map(
          unit =>
            unit.context
              .sheet_name
        )
        .filter(Boolean)
    );


  // ==========================================================
  // РЕЗУЛЬТАТ
  // ==========================================================

  return {

    ...input,


    analysis_units:
      analysisUnits,


    analysis_unit_building: {

      version:
        '1.3',


      config: {

        approx_chars_per_token:
          CONFIG
            .approxCharsPerToken,


        max_primary_approx_tokens:
          CONFIG
            .maxPrimaryApproxTokens,


        recommended_analysis_range_tokens: {

          from:
            2500,

          to:
            3500,
        },


        overlap_semantic_blocks:
          CONFIG
            .overlapSemanticBlocks,


        // Новые правила v1.3

        prevent_cross_sheet_units:
          true,


        tables_allowed_as_overlap:
          false,
      },


      source_semantic_blocks_count:
        semanticBlocks.length,


      source_sections_count:
        sections.length,


      analysis_units_count:
        analysisUnits.length,


      split_sections_count:
        splitSectionsCount,


      // ------------------------------------------------------
      // XLSX СТАТИСТИКА
      // ------------------------------------------------------

      sheet_partitions_count:
        [
          ...unitsByPartition.keys(),
        ]
          .filter(
            key => {

              const parsed =
                JSON.parse(
                  key
                );


              return (
                parsed[1] !==
                null
              );
            }
          )
          .length,


      spreadsheet_sheets_in_units_count:
        spreadsheetSheetNames.length,


      spreadsheet_sheets_in_units:
        spreadsheetSheetNames,


      units_with_spreadsheet_context_count:
        analysisUnits
          .filter(
            unit =>
              unit.context
                .sheet_name !==
              null
          )
          .length,


      units_with_sheet_title_context_count:
        analysisUnits
          .filter(
            unit =>
              unit.context
                .sheet_title !==
              null
          )
          .length,


      // ------------------------------------------------------
      // OVERLAP
      // ------------------------------------------------------

      units_with_overlap_count:
        analysisUnits
          .filter(
            unit =>
              unit
                .overlap_semantic_block_ids
                .length > 0
          )
          .length,


      // ------------------------------------------------------
      // ТАБЛИЦЫ
      // ------------------------------------------------------

      units_with_tables_count:
        analysisUnits
          .filter(
            unit =>
              unit.flags
                .contains_table
          )
          .length,


      oversized_atomic_units_count:
        analysisUnits
          .filter(
            unit =>
              unit.flags
                .oversized_atomic_block
          )
          .length,


      units_over_recommended_max_count:
        unitsOverRecommendedMax.length,


      units_over_recommended_max:
        unitsOverRecommendedMax,


      // ------------------------------------------------------
      // COVERAGE
      // ------------------------------------------------------

      missing_semantic_blocks_count:
        missingSemanticBlocks.length,


      missing_semantic_blocks:
        missingSemanticBlocks,


      duplicated_primary_semantic_blocks_count:
        duplicatedPrimarySemanticBlocks.length,


      duplicated_primary_semantic_blocks:
        duplicatedPrimarySemanticBlocks,


      primary_coverage:
        primaryCoverage,


      data_loss:
        missingSemanticBlocks.length >
        0,


      warnings,
    },
  };
}


